from research_helpers import *
a=ev('https://www.sec.gov/Archives/edgar/data/1694665/000169466520000017/evelo10-k12312019.htm','Historical issuer annual report identifies EDP1815/1503/1867/2939/1632 and discontinued EDP1066. Historical preclinical/clinical status not current activity proof.')
b=ev('https://www.sec.gov/Archives/edgar/data/1694665/000169466520000079/evlo-20200630.htm','Issuer describes SINTAX small intestinal axis platform and five then-active monoclonal microbial candidates including neuroinflammatory EDP1632.')
c=ev('https://www.globenewswire.com/news-release/2023/04/26/2654930/0/en/Evelo-Biosciences-Provides-Clinical-Updates.html','Issuer ends EDP1815 atopic-dermatitis development,not all EDP1815 indications; describes next-generation EV platform and EDP2939 derived from same strain but different product format.')
d=ev('https://www.globenewswire.com/news-release/2023/10/17/2761342/0/en/Evelo-Biosciences-Announces-Top-Line-Results-From-its-Phase-2-Clinical-Study-with-EDP2939-in-Moderate-Psoriasis.html','Issuer ceases EDP2939 development after Phase2 endpoint failure; seeks EDP1815/SINTAX partners.')
e=ev('https://www.sec.gov/Archives/edgar/data/1694665/000119312524016885/d650325d8k.htm','January2024 issuer dissolution approval/process disclosed. Actual later asset transfer,successor ownership and final dissolution certificate not established by this filing; no current marketed-product claim.')
specs=[('EDP1815','Historical oral monoclonal microbial candidate; atopic-dermatitis development ceased2023 while other partnering sought.','unknown',[a,c,d,e]),('EDP2939','Microbial extracellular-vesicle candidate; development stopped October2023 after Phase2 psoriasis results.','discontinued',[a,c,d,e]),('EDP1503','Historical investigational oral microbial oncology candidate,including combination trials.','unknown',[a,b,e]),('EDP1867','Historical non-replicating microbial inflammatory-disease candidate.','unknown',[a,b,e]),('EDP1632','Historical preclinical microbial neuroinflammation candidate.','unknown',[a,b,e]),('EDP1066','Microbial inflammation candidate discontinued February2020.','discontinued',[a,e])]
products=[p(n,desc,evs[0],life,evidence=evs) for n,desc,life,evs in specs]
products+=[p('Evelo SINTAX platform','Historical small-intestinal-axis drug-discovery platform; successor commercialization unverified.',b,'unknown',typ='technology',evidence=[b,d,e]),p('Evelo microbial extracellular-vesicle platform','Historical next-generation EV drug platform; separate from whole-microbe candidate identities.',c,'unknown',typ='technology',evidence=[c,d,e])]
co=company('Evelo Biosciences Inc',products,[a,b,c,d,e],'Six historically named candidates and two technologies entered. EDP2939 andEDP1066 explicitly discontinued; no blanket termination inferred solely from dissolution process. EDP1815 atopic-only stop not global programme stop. Current rights/successor transactions,latest dissolution status and any remaining legacy discovery codes still need primary evidence; historic products not presented commercially available.')
(out/'batch-0139.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
